import {inspectorDocument,patchElement} from './visual-editor.js';
import * as admin from './admin.js';
import * as accounts from './accounts.js';
import * as ai from './ai-client.js';
import {MODELS,parseGeneration} from './ai-core.js';
import {OPTIONS} from './providers.js';
import {STORAGE_KEY,MAX_IMPORT,escapeHtml as e,normalizeBackup,starterFiles,buildDocument,validateUrl,importEvidence} from './core.js';
const $=s=>document.querySelector(s);
let state={version:1,projects:[],settings:{name:'Meu espaço',autosave:true}};
let loadError='',damagedCloud=null;
try{const saved=localStorage.getItem(STORAGE_KEY);if(saved)state=normalizeBackup(JSON.parse(saved));}catch{loadError='Não foi possível ler os dados salvos. Nada foi sobrescrito. Exporte ou restaure seu backup antes de continuar.';}
let picking=false,pickToken='',pickSelection=null;
let query='',filter='all',fileMode='html',editorTab='code',viewport='desktop',dirty=false,draft=null,currentId=null,timer,importMode='backup',importProjectId=null,importOwner=null,confirmAction;
const names={projects:'Meus projetos',activity:'Atividade',skills:'Recursos de criação',extension:'Extensão',settings:'Preferências',admin:'Administração da plataforma',guide:'Guia rápido'};
const date=s=>{const d=new Date(s);return Number.isNaN(d.getTime())?'Agora':d.toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function persist(next,{recover=false}={}){if(!accounts.writable()){toast('Aguarde ou entre na sua conta antes de salvar.');return false;}if(accounts.account.enabled&&accounts.account.error){toast('Não sincronizado: exporte um backup antes de recarregar.');return false;}if(loadError&&!recover){toast('Os dados salvos precisam de recuperação. Restaure um backup ou apague o espaço explicitamente.');return false;}try{if(accounts.account.enabled){accounts.save(next).catch(err=>toast(err.message));}else localStorage.setItem(STORAGE_KEY,JSON.stringify(next));state=next;loadError='';updateShell();return true;}catch{toast('Não foi possível salvar. O navegador pode estar sem espaço. Exporte seu projeto antes de sair.');return false;}}
function updateShell(){const a=accounts.account;const adminLink=$('#admin-link');if(adminLink)adminLink.hidden=!a.isAdmin;const link=$('#account-link');if(link)link.textContent=a.user?'Minha conta':'Entrar / cadastro';const pill=$('.local-pill');if(pill)pill.textContent=a.enabled?(a.sync||'Conta protegida'):'Local · sem login';$('#nav-count').textContent=state.projects.length;$('#workspace-name').textContent=state.settings.name;}
function download(name,content,type='application/json'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function exportBackup(){if(loadError){try{download('baixatudo-dados-para-recuperacao.json',accounts.account.enabled?JSON.stringify(damagedCloud||{}):localStorage.getItem(STORAGE_KEY)||'{}');toast('Dados originais exportados para recuperação.');}catch{toast('O navegador bloqueou a leitura dos dados.');}return;}if(dirty&&!saveDraft())return;download('baixatudo-backup.json',JSON.stringify(state,null,2));toast('Backup preparado. Guarde o arquivo em um lugar seguro.');}
function confirm(title,text,action){$('#confirm-title').textContent=title;$('#confirm-text').textContent=text;const owner=accounts.account.owner;confirmAction=()=>{if(owner!==accounts.account.owner)return toast('A conta mudou. Abra a ação novamente.');action();};$('#confirm-dialog').showModal();}
$('#confirm-cancel').onclick=()=>$('#confirm-dialog').close();$('#confirm-ok').onclick=()=>{$('#confirm-dialog').close();confirmAction?.();};
function createProject(){if(!accounts.writable())return toast('Entre na sua conta ou aguarde o carregamento.');if(dirty&&!saveDraft())return;$('#project-form').reset();$('#project-dialog').showModal();}
$('#project-dialog').addEventListener('click',ev=>{if(ev.target.closest('[data-close]'))$('#project-dialog').close();});
$('#project-form').onsubmit=ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(ev.target));try{const target=validateUrl(data.target);const name=data.name.trim();if(!name)return toast('Digite um nome para o projeto.');const now=new Date().toISOString();const p={id:crypto.randomUUID(),name,target,createdAt:now,updatedAt:now,brief:data.brief,relation:data.relation,excluded:data.excluded,files:starterFiles(name),evidence:[],versions:[]};if(!persist({...state,projects:[p,...state.projects]}))return;$('#project-dialog').close();query='';filter='all';location.hash='project/'+p.id;render();toast('Projeto preparado. Importe uma referência e escolha a IA ou o modo sem API.');}catch(err){toast(err.message);}};
function heading(kicker,title,description,actions=''){return `<div class="page-heading"><div><span class="kicker">${kicker}</span><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
function stat(icon,value,label,note){return `<div class="stat"><span class="stat-icon">${icon}</span><div><strong>${value}</strong><span>${label}</span></div><small>${note}</small></div>`;}
function projectsPage(){
 const shown=state.projects.filter(p=>(p.name+' '+p.target).toLowerCase().includes(query.toLowerCase())&&(filter!=='evidence'||p.evidence.length)).sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt));
 return heading('SEU ESPAÇO DE CRIAÇÃO','Ideias que ganham forma.','Planeje, experimente e construa. Tudo começa com um projeto.',`<button class="button secondary" data-action="import-start">Importar referência / arquivo</button><button class="button secondary" data-action="backup">↥ <span>Exportar backup</span></button><button class="button primary" data-action="new">＋ Novo projeto</button>`)+
 `<section class="hero"><div class="hero-copy"><span class="hero-tag"><i></i> SEU PRÓXIMO PROJETO COMEÇA AQUI</span><h2>Da referência<br>à sua próxima ideia<span>.</span></h2><p>Um lugar para organizar o que inspira você,<br>editar seu código e acompanhar cada detalhe.</p><button class="button lime" data-action="new">Criar meu projeto <span>↗</span></button><small>Referência, projeto e edição. No seu ritmo.</small></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="art-label">IDEIA → CÓDIGO → PRÉVIA</div><div class="art-window"><div class="window-dots"><i></i><i></i><i></i><span>seu-projeto.html</span></div><div class="mini-page"><div class="mini-nav"><b>studio.</b><span>✳</span></div><div class="mini-eyebrow">UM ESPAÇO PARA O NOVO</div><div class="mini-title">Imagine.<br>Crie. Repita.</div><div class="mini-line"></div><div class="mini-line short"></div><div class="mini-button">Explorar possibilidades ↗</div><div class="mini-shape">✳</div></div></div><div class="floating-code">〈/〉 <span>Feito por você</span></div><div class="floating-check">✓ <span>Uma ideia de cada vez</span></div></div></section>`+
 `<section class="stats" aria-label="Resumo">${stat('▦',state.projects.length,'Projetos no espaço','Seu acervo pessoal')}${stat('◈',state.projects.reduce((n,p)=>n+p.evidence.length,0),'Referências importadas','Capturas organizadas')}${stat('↶',state.projects.reduce((n,p)=>n+p.versions.length,0),'Versões salvas','Liberdade para experimentar')}${stat('⌁',accounts.account.enabled?'Conta':'Local','Armazenamento',accounts.account.enabled?'Sincronizado com seu usuário':'Neste navegador')}</section>`+
 `<section class="project-section"><div class="section-title"><div><h2>Seus projetos <span>${state.projects.length.toString().padStart(2,'0')}</span></h2><p>Retome de onde a sua última ideia parou.</p></div><label class="search"><span>⌕</span><input id="search" type="search" placeholder="Buscar projeto..." value="${e(query)}" aria-label="Buscar projetos"><kbd>/</kbd></label></div><div class="project-toolbar"><div class="tabs"><button data-filter="all" class="${filter==='all'?'active':''}">Todos os projetos</button><button data-filter="evidence" class="${filter==='evidence'?'active':''}">Com referências</button></div><span class="sort-label">Última atualização ↓</span></div><div class="project-grid">${shown.map(card).join('')}${!query&&filter==='all'?`<button class="new-project-card" data-action="new"><span>＋</span><strong>Uma nova possibilidade</strong><small>Crie um projeto do seu jeito</small></button>`:''}</div>${!shown.length&&(query||filter!=='all')?'<div class="empty-inline">Nenhum projeto encontrado. Tente outro nome ou filtro.</div>':''}</section>`+
 `<div class="bottom-note"><span>ⓘ</span><p><strong>Um ponto de partida honesto.</strong> Editor e prévia estão disponíveis. A geração usa IA local neste aparelho, após ativação. A captura simples não revela o backend do site.</p><a href="#skills">Ver ferramentas →</a></div>`;
}
function card(p){return `<article class="project-card"><a href="#project/${p.id}" class="project-cover"><div class="cover-abstract"><span class="cover-browser">● ● ● <b>${e(p.name.slice(0,25))}</b></span><div class="cover-layout"><i></i><div><b>${e(p.name.slice(0,30))}</b><span></span><span></span><em></em></div></div></div><span class="cover-open">Abrir projeto ↗</span></a><div class="project-info"><div class="project-name-row"><a href="#project/${p.id}"><h3>${e(p.name)}</h3></a><button class="icon-button" data-delete="${p.id}" aria-label="Excluir ${e(p.name)}">×</button></div><p>${e(p.target?new URL(p.target).hostname:'Projeto original · sem referência')}</p><div class="project-meta"><span class="badge">Em edição</span><small>Atualizado em ${date(p.updatedAt)}</small></div></div></article>`;}
function selected(){return state.projects.find(p=>p.id===currentId);}
function saveDraft(){const p=selected();if(!p||!dirty)return true;const updated={...p,files:{...draft},updatedAt:new Date().toISOString()};if(!persist({...state,projects:state.projects.map(x=>x.id===p.id?updated:x)}))return false;dirty=false;const el=$('#save-status');if(el)el.textContent=accounts.account.enabled?accounts.account.sync:'Salvo neste navegador';return true;}
function editorPage(p){
 return `<div class="editor-heading"><a href="#projects" class="back-link">← Meus projetos</a><div class="editor-title-row"><div><h1>${e(p.name)}</h1><span id="save-status" class="muted">${e(accounts.account.enabled?accounts.account.sync:'Salvo neste navegador')}</span></div><div class="heading-actions"><button class="button secondary" data-action="snapshot">↶ Salvar versão</button><button class="button primary" data-action="export-html">↧ Exportar HTML</button></div></div></div><div class="notice editor-notice"><strong>Seu projeto, no seu controle.</strong> A IA gera rascunhos próprios a partir das referências. Revise o resultado antes de usar; não recupera o servidor do site original.</div><div class="editor-tabs tabs"><button data-editor-tab="code" class="${editorTab==='code'?'active':''}">〈/〉 Código e prévia</button><button data-editor-tab="brief" class="${editorTab==='brief'?'active':''}">☷ Entrevista</button><button data-editor-tab="evidence" class="${editorTab==='evidence'?'active':''}">◈ Referências (${p.evidence.length})</button><button data-editor-tab="versions" class="${editorTab==='versions'?'active':''}">↶ Versões (${p.versions.length})</button></div>${editorTab==='code'?`${aiPanel(p)}<section class="panel visual-tools"><h2>Editor visual · HTML</h2><p>Ative a seleção e toque em um elemento da prévia. Altere texto simples, cores, tamanho, ordem ou remova o elemento. Desative para testar os botões normalmente. Não edita componentes criados por JavaScript nem o backend.</p><button class="button secondary" id="pick-toggle">${picking?'Desativar seleção visual':'Selecionar na prévia'}</button><p id="visual-status" role="status">Nenhum elemento selecionado.</p><form id="visual-form"><fieldset disabled><div class="quick-grid"><label>Texto simples<input name="text" maxlength="2000"></label><label>Cor do texto<input name="color" type="color" value="#26372e"></label><label>Cor do fundo<input name="background" type="color" value="#ffffff"></label><label>Fonte (px)<input name="fontSize" type="number" min="8" max="160" value="24"></label></div><div class="heading-actions"><button class="button primary">Aplicar na prévia e salvar</button><button class="button secondary" type="button" data-visual="up">Mover antes</button><button class="button secondary" type="button" data-visual="down">Mover depois</button><button class="button danger" type="button" data-visual="remove">Remover elemento</button></div></fieldset></form><p>Alterações visuais preservam uma versão anterior automaticamente. Scripts e CSS do projeto continuam na prévia isolada; alterar estrutura ou IDs pode exigir ajustes no código.</p></section><details class="quick-edit"><summary>✧ Ajustes rápidos · sem mexer no código</summary><form id="quick-form"><div class="quick-grid"><label>Título principal<input name="title" maxlength="300" placeholder="Novo título da página"></label><label>Cor de fundo<input name="background" type="color" value="#f5f1e9"></label><label>Cor do texto<input name="foreground" type="color" value="#26372e"></label><button class="button primary">Aplicar ajustes</button></div><p>Altera o primeiro título H1 e as cores da página. Os campos de cor começam com as cores do modelo inicial. Funciona sem IA; salve uma versão antes de experimentar.</p></form></details><div class="editor-layout"><section class="code-pane"><div class="pane-toolbar"><div class="file-tabs">${['html','css','js'].map(f=>`<button data-file="${f}" class="${fileMode===f?'active':''}">${f==='html'?'index.html':f==='css'?'style.css':'script.js'}</button>`).join('')}</div><button class="text-button" data-action="save">Salvar</button></div><label class="sr-only" for="code">Código ${fileMode}</label><textarea id="code" spellcheck="false" autocapitalize="off" autocomplete="off">${e(draft[fileMode])}</textarea><div class="pane-footer">${fileMode.toUpperCase()} <span>Arquivos locais · edição local</span></div></section><section class="preview-pane"><div class="pane-toolbar"><strong>Prévia</strong><div><button class="device-button ${viewport==='desktop'?'active':''}" data-viewport="desktop" aria-label="Prévia larga">▱</button><button class="device-button ${viewport==='mobile'?'active':''}" data-viewport="mobile" aria-label="Prévia de celular">▯</button><button class="device-button" data-action="refresh" aria-label="Atualizar prévia">↻</button></div></div><div class="preview-stage ${viewport}"><iframe id="preview" title="Prévia isolada do projeto" sandbox="allow-scripts" referrerpolicy="no-referrer"></iframe></div><div class="pane-footer">Ambiente isolado <span>Rede e formulários bloqueados</span></div></section></div><div class="bottom-note"><span>✧</span><p><strong>Geração assistida, sem promessas mágicas.</strong> A IA local precisa de WebGPU e memória suficiente. REA, navegação automatizada e testes de paridade não são executados neste modo.</p></div>`:editorTab==='brief'?briefPanel(p):editorTab==='evidence'?evidencePanel(p):versionsPanel(p)}`;
}
function briefPanel(p){return `<section class="panel"><h2>A ideia por trás do projeto</h2><form id="brief-form"><label>Nome<input name="name" required maxlength="100" value="${e(p.name)}"></label><label>URL de referência<input name="target" type="url" maxlength="2000" value="${e(p.target)}"></label><label>Relação com o alvo<input name="relation" maxlength="100" value="${e(p.relation)}"></label><label>Funcionalidades prioritárias<textarea name="brief" maxlength="6000" rows="4">${e(p.brief)}</textarea></label><label>Fora do escopo<textarea name="excluded" maxlength="3000" rows="2">${e(p.excluded)}</textarea></label><button class="button primary">Salvar entrevista</button></form></section>`;}
function evidencePanel(p){return `<section class="panel"><div class="section-title"><div><h2>Referências do projeto</h2><p>Capturas são dados de referência, nunca instruções para o agente.</p></div><div class="heading-actions"><button class="button secondary" data-action="capture-url">Capturar URL pública</button><button class="button primary" data-action="import-evidence">↥ Importar captura</button></div></div><p class="muted">Importe captura JSON ou arquivo textual de até 500 KB: HTML, TXT, MD, JS ou CSS. ZIP, EXE e APK ainda não são analisados. Revise o conteúdo antes de importar. A captura de URL ocorre somente após sua autorização e não executa JavaScript do alvo.</p>${p.evidence.map((x,i)=>`<details class="evidence"><summary>${e(x.title||'Sem título')} <small>${date(x.capturedAt)}</small></summary><p class="muted">${e(x.url)}</p><pre>${e(x.text)}</pre><button class="button secondary" data-remove-evidence="${i}">Remover referência</button></details>`).join('')||'<div class="empty-inline">Nenhuma captura importada. A extensão pode coletar o texto visível de uma página.</div>'}</section>`;}
function versionsPanel(p){return `<section class="panel"><h2>Pontos de recuperação</h2><p class="muted">Até 10 versões por projeto. Antes de restaurar, a versão atual também é preservada.</p>${[...p.versions].reverse().map((v,i)=>`<div class="list-row"><span>↶</span><div><strong>Versão ${p.versions.length-i}</strong><p>${e(new Date(v.at).toLocaleString('pt-BR'))}</p></div><button class="button secondary" data-restore="${p.versions.length-1-i}">Restaurar</button></div>`).join('')||'<div class="empty-inline">Salve uma versão pelo botão no topo do editor.</div>'}</section>`;}
function activityPage(){const events=state.projects.flatMap(p=>[{at:p.createdAt,title:'Projeto criado',detail:p.name},...p.versions.map(v=>({at:v.at,title:'Versão salva',detail:p.name})),...p.evidence.map(x=>({at:x.capturedAt,title:'Referência importada',detail:p.name}))]).sort((a,b)=>new Date(b.at)-new Date(a.at));return heading('SEU PERCURSO','Cada passo conta.','Um registro local do que você está construindo.')+`<section class="panel">${events.map(x=>`<div class="list-row"><span class="event-icon">↗</span><div><strong>${e(x.title)}</strong><p>${e(x.detail)}</p></div><small>${date(x.at)}</small></div>`).join('')||'<div class="empty-inline">Sua história começa com o primeiro projeto.</div>'}</section>`;}
function skillsPage(){return heading('RECURSOS DO SEU ESTÚDIO','Crie sem cuidar dos bastidores.','Escolha o que quer fazer. O sistema organiza as orientações internas.')+`<div class="tools-grid"><section class="tool-card"><span class="tool-icon">◈</span><span class="badge">Disponível</span><h2>Preparar referência</h2><p>Capture HTML público ou importe texto renderizado pela extensão. A captura não acessa páginas privadas nem executa scripts.</p></section><section class="tool-card"><span class="tool-icon">✧</span><span class="badge neutral">Requer ativação da IA</span><h2>Recriar e melhorar</h2><p>Geração local de rascunhos HTML/CSS/JS e melhorias de interface. Precisa de WebGPU, download de modelo e memória no aparelho.</p><a class="text-link" href="#settings">Preparar IA →</a></section><section class="tool-card"><span class="tool-icon">✓</span><span class="badge neutral">Revisão, não teste automático</span><h2>Revisar qualidade</h2><p>A IA pode sugerir correções. Isso não substitui testes de fluxo, acessibilidade ou paridade.</p></section></div><div class="bottom-note"><span>ⓘ</span><p>Uso pessoal não comercial. Metodologia interna: clonar-programa, de Dark Sem Filtro. Orientações de design e revisão: Anthropic. Avisos e licenças são preservados.</p><a href="/public/licenses/provenance.json" target="_blank" rel="noopener noreferrer">Créditos e versões ↗</a></div>`;}
function extensionPage(){return heading('UMA PONTE PARA SUAS REFERÊNCIAS','Leve a inspiração com você.','Uma extensão pequena, com captura explícita e permissão solicitada para o site escolhido.')+`<section class="panel extension-intro"><span class="extension-symbol">◈</span><div><span class="badge">Extensão v0.3.1 · instalação manual</span><h2>Baixatudo · Captura pessoal</h2><p>A extensão lê o texto visível somente quando você pede. Você revisa e edita o conteúdo antes de salvar uma captura JSON. Depois, importa o arquivo no seu projeto.</p><a class="button primary" href="/public/baixatudo-extension.zip?v=0.3.1" download>↧ Baixar extensão (.zip)</a><p>Atualização 0.3.1: proteção adicional para não capturar texto de formulários na leitura de abas, além das opções de aba, endereço e arquivo e do envio para a importação no Studio.</p><p><strong>Já instalou uma versão anterior?</strong> Baixe o novo ZIP, extraia em uma pasta e atualize a extensão pelo gerenciador do navegador. Se o navegador exigir reinstalação, remova a versão antiga e carregue a pasta nova. Confira a versão 0.3.1 nos detalhes. Baixar o ZIP sozinho não atualiza a instalação.</p><p class="muted">Chrome/Edge desktop: instalação manual. Android: compatibilidade não validada. Não está publicada em lojas.</p></div></section><div class="steps-grid"><section class="panel"><b class="step-number">01</b><h3>No computador</h3><p>Extraia o ZIP. Abra a página de extensões, habilite o modo de desenvolvedor e escolha “Carregar sem compactação”. Selecione a pasta extraída.</p></section><section class="panel"><b class="step-number">02</b><h3>Capture com cuidado</h3><p>Abra uma página própria ou autorizada. Clique na extensão, capture e remova dados privados. Salve o arquivo JSON.</p></section><section class="panel"><b class="step-number">03</b><h3>Traga para o Studio</h3><p>Abra um projeto, vá a Referências e importe a captura. Não são coletados cookies, senhas, formulários ou código do servidor.</p></section></div><div class="notice">No seu Android, use o painel web. “Modo computador” não instala extensões. A extensão não executa a skill nem faz clonagem automática.</div>`;}
function providerPanel(){const p=ai.getProfile();return `<section class="panel"><h2>Escolher IA · agora ou no futuro</h2><form id="provider-form"><label>Como trabalhar<select name="provider" id="provider-choice">${OPTIONS.map(x=>`<option value="${x.id}" ${p.provider===x.id?'selected':''}>${e(x.name)}</option>`).join('')}</select></label><label>Identificador do modelo<input name="model" value="${e(p.model)}" maxlength="160" placeholder="OpenRouter gratuito: openrouter/free"></label><p class="muted">Para Gemini, GPT ou Groq, use o identificador disponível na sua conta. Não presumimos que todo modelo esteja incluído na cota gratuita.</p><label>Chave da sua conta · somente nesta aba<input name="apiKey" type="password" autocomplete="off" maxlength="512" placeholder="Nunca cole sua chave no chat ou na referência"></label><p class="muted">${ai.keyPresent()?'Há uma chave apenas na memória desta aba. Salvar novamente sem preenchê-la remove a chave anterior.':'Nenhuma chave carregada.'} A chave não entra no backup, no GitHub ou no armazenamento do navegador. É transmitida por HTTPS ao servidor da aplicação e ao provedor escolhido para cada pedido. Não é um cofre permanente.</p><label class="checkbox"><input name="freeOnly" type="checkbox" ${p.freeOnly?'checked':''}> OpenRouter: bloquear modelos pagos</label><label class="checkbox"><input name="allowMetered" type="checkbox" ${p.allowMetered?'checked':''}> Fora do modo gratuito do OpenRouter, entendo que limites e possíveis custos dependem da minha conta no provedor.</label><p class="muted">O aplicativo não verifica nem altera seu faturamento. Não ative cobrança se deseja testar sem gastar. Nenhum fallback para provedor pago é automático.</p><div class="stack-actions"><button class="button primary" type="submit">Salvar e selecionar</button><button class="button secondary" type="button" data-action="forget-key">Remover chave da aba</button></div></form><details><summary>Qual opção gratuita escolher?</summary><p>Sem chave: validação manual com uma IA que você já utiliza, ou WebLLM em aparelho compatível. OpenRouter: exige conta e chave; use openrouter/free. Gemini e Groq: a disponibilidade gratuita depende do modelo e da conta. OpenAI API não é a mesma coisa que usar o ChatGPT gratuito.</p><p>As opções com API estão implementadas, mas a conexão real só pode ser validada com uma chave sua. Nenhuma foi cadastrada ou ativada por nós.</p><a class="text-link" href="/public/PESQUISA-IA.md" target="_blank" rel="noopener noreferrer">Pesquisa e fontes oficiais ↗</a></details><div class="ai-status" role="status">${e(ai.runtime.message)}</div></section>`;}
function importLanding(){return heading('DA EXTENSÃO PARA SEU PAINEL','Transformar referência em projeto.','O arquivo JSON contém a referência, não um clone pronto. Selecione o arquivo baixado para criar o projeto no painel.')+`<section class="panel"><button class="button primary" data-action="import-start">Selecionar captura ou arquivo</button><p>Você não precisa abrir o JSON como página nem copiar o código dele. Após selecionar, o Studio cria o projeto e abre seu editor.</p><p>Use apenas referências próprias ou autorizadas. Não importe dados privados ou chaves.</p></section>`;}
function accountBanner(){const a=accounts.account;return a.status==='local'?`<div class="notice account-notice"><strong>Modo local · sem login.</strong> Seus projetos ficam somente neste navegador e endereço. Cadastro e armazenamento em conta ainda não estão ativos. <a href="#account">Ver situação da conta</a></div>`:a.error?`<div class="notice error" role="alert">${e(a.sync)}. ${e(a.error)} Faça um backup antes de sair.</div>`:'';}
function accountPage(){const a=accounts.account;const adminLogin=location.hash==='#admin';if(a.status==='loading')return heading('SUA CONTA','Carregando…','Aguardando o serviço de contas.');
 if(a.status==='local')return heading('ACESSO POR USUÁRIO','Cadastro ainda não ativado.','A conexão do Supabase precisa ser reautenticada e o banco configurado.')+`<section class="panel"><p>${e(a.reason)}</p><p>Não criamos contas fictícias nem usamos senha local como proteção. Não utilize o modo local em aparelho compartilhado para dados privados. Antes de mudar de navegador, exporte um backup.</p><a class="button secondary" href="#projects">Voltar aos projetos locais</a></section>`;
 if(a.status==='error')return heading('CONEXÃO INDISPONÍVEL','Não foi possível carregar sua conta.',e(a.error))+`<section class="panel"><button class="button secondary" data-auth="reload">Tentar novamente</button>${a.user?'<button class="button secondary" data-auth="logout">Sair desta conta</button>':''}</section>`;
 if(a.user)return heading('SEU ACESSO','Minha conta.',e(a.user.email||'Conta conectada'))+`<section class="panel"><p>Os projetos são carregados da sua conta. Nenhum projeto local antigo é importado automaticamente.</p><p role="status">${e(a.sync)}</p>${a.isAdmin?'<a class="button primary" href="#admin">Abrir painel administrativo</a>':''}${a.platformError?`<p role="alert">${e(a.platformError)}</p>`:''}${a.platform?`<p>IA remota: ${e(a.platform.aiUsed)} de ${e(a.platform.aiLimit)} solicitações utilizadas. ${a.platform.blocked?'APIs bloqueadas pelo administrador.':''}</p>`:''}<form id="account-form"><input type="hidden" name="mode" value="password"><label>Nova senha<input type="password" name="password" minlength="12" required autocomplete="new-password"></label><button class="button secondary">Atualizar senha</button></form><button class="button secondary" data-auth="logout">Sair da minha conta</button><p id="account-message" role="status"></p></section>`;
 return heading(adminLogin?'ÁREA ADMINISTRATIVA':'CADA PESSOA, SEU ESPAÇO',adminLogin?'Entrar na administração.':'Entre ou crie sua conta.',adminLogin?'Use a conta autorizada e sua senha atual. Sem senha administrativa compartilhada.':'Projetos separados por usuário, protegidos pelas regras do banco.')+`<section class="panel auth-panel"><form id="account-form"><label>Ação<select name="mode"><option value="login">Entrar</option>${adminLogin?'':'<option value="signup">Criar conta</option>'}<option value="reset">Recuperar senha</option></select></label><label>E-mail<input type="email" name="email" required autocomplete="email"></label><label>Senha<input type="password" name="password" minlength="1" autocomplete="current-password"></label><p class="muted">No cadastro, use ao menos 12 caracteres e confirme o e-mail, se solicitado. Recuperar senha usa apenas seu e-mail.</p><button class="button primary">Continuar</button></form><p id="account-message" role="status"></p></section>`;
}
function bindAccount(){
 $('#account-form [name=mode]')?.addEventListener('change',event=>{const input=$('#account-form [name=password]');if(input){input.value='';input.required=event.target.value!=='reset';input.minLength=event.target.value==='signup'?12:1;input.autocomplete=event.target.value==='signup'?'new-password':'current-password';}});
 $('#account-form')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,data=new FormData(form),mode=String(data.get('mode'));const email=String(data.get('email')||'').trim(),password=String(data.get('password')||'');if((mode==='signup'||mode==='password')&&password.length<12)return $('#account-message').textContent='Use uma senha com pelo menos 12 caracteres.';const button=form.querySelector('button');button.disabled=true;try{const message=await accounts.submit(mode,email,password);form.reset();if($('#account-message'))$('#account-message').textContent=message;}catch(error){if($('#account-message'))$('#account-message').textContent=error.message;}finally{button.disabled=false;}});
 document.querySelectorAll('[data-auth]').forEach(button=>button.onclick=()=>{if(button.dataset.auth==='reload')return location.reload();if(dirty&&!saveDraft())return;accounts.logout().catch(error=>confirm('Sair sem sincronizar?',error.message+' Baixe um backup dos projetos antes de sair. Esta ação descarta apenas as mudanças ainda não enviadas nesta sessão.',()=>accounts.logout({discard:true}).catch(err=>toast(err.message))));});
}
window.addEventListener('account-reset',()=>{ai.forgetKey();picking=false;pickSelection=null;loadError='';damagedCloud=null;clearTimeout(timer);dirty=false;draft=null;currentId=null;confirmAction=null;query='';filter='all';state={version:1,projects:[],settings:{name:'Meu espaço',autosave:true}};document.querySelectorAll('dialog[open]').forEach(d=>d.close());updateShell();render();});
window.addEventListener('account-workspace',event=>{try{state=normalizeBackup(event.detail.workspace);loadError='';if(!location.hash||location.hash==='#account')location.hash='projects';render();}catch{damagedCloud=event.detail.workspace;loadError='Os dados da conta não puderam ser validados. Não foram substituídos.';render();}});
window.addEventListener('account-change',()=>render());
window.addEventListener('admin-change',()=>{if(location.hash==='#admin')render();});
window.addEventListener('account-sync',()=>{updateShell();if($('#save-status'))$('#save-status').textContent=accounts.account.sync;if(accounts.account.error)toast(accounts.account.sync);});
function settingsPage(){return heading('NO SEU CONTROLE','Preferências do espaço.','Configurações pessoais, armazenamento e proteção do seu trabalho.')+`<div class="settings-grid"><section class="panel"><h2>Seu espaço</h2><form id="settings-form"><label>Nome do workspace<input name="name" maxlength="80" required value="${e(state.settings.name)}"></label><label class="checkbox"><input name="autosave" type="checkbox" ${state.settings.autosave?'checked':''}> Salvar alterações de código automaticamente</label><p class="muted">${accounts.account.enabled?'Preferências do usuário autenticado. A administração global de usuários não está incluída neste painel.':'Sem chave obrigatória. Esta área é local; não representa uma barreira de autenticação.'}</p><button class="button primary">Salvar configurações</button></form></section><section class="panel"><h2>Backup e recuperação</h2><p>${accounts.account.enabled?'Seus projetos são sincronizados com a conta. Aguarde a indicação Salvo na conta antes de sair.':'Seus dados ficam neste navegador e neste endereço. Não há sincronização entre dispositivos ou navegadores.'}</p><div class="storage-bar"><span></span></div><p class="muted">${(new Blob([JSON.stringify(state)]).size/1024).toFixed(1)} KB de dados · cota definida pelo navegador</p><div class="stack-actions"><button class="button secondary" data-action="backup">↧ Exportar backup completo</button><button class="button secondary" data-action="import-backup">↥ Restaurar backup</button></div><p class="muted">Limpar dados do navegador pode apagar seus projetos. Guarde backups fora dele.</p></section>${providerPanel()}<section class="panel"><h2>IA pessoal · sem conta</h2><p>O modelo roda neste aparelho, não nos servidores da Vercel. O primeiro uso baixa centenas de MB ou mais de 1 GB. Prefira Wi-Fi; não há cobrança de API, mas sua internet pode ter custo.</p><label for="ai-model">Modelo<select id="ai-model">${MODELS.map(m=>`<option value="${m.id}" ${ai.runtime.model===m.id?'selected':''}>${m.name}</option>`).join('')}</select></label><p class="muted">${MODELS.map(m=>`${m.name}: ${m.memory}`).join('<br>')}</p><div class="local-ai-status" role="status">Verifique a compatibilidade antes de baixar um modelo. Falta de GPU afeta somente este modo.</div><progress class="ai-progress" max="1" value="${ai.runtime.progress}"></progress><div class="stack-actions"><button class="button secondary" data-action="check-ai">Verificar aparelho</button><button class="button primary" data-action="activate-ai">Ativar IA</button><button class="button secondary" data-action="cancel-ai">Desativar / cancelar</button></div><p class="muted">Compatibilidade e qualidade não foram validadas no seu Android. Modelos ficam no cache do navegador; limpar os dados pode exigir novo download. Não há garantia de funcionamento em todo aparelho.</p></section><section class="panel danger-panel"><h2>${accounts.account.enabled?'Apagar projetos da conta':'Apagar dados locais'}</h2><p>Remove projetos, referências e versões ${accounts.account.enabled?'da sua conta':'deste navegador'}. Exporte um backup antes.</p><button class="button danger" data-action="clear">Apagar meu espaço</button></section></div>`;}
function guidePage(){return heading('SIMPLES, DO PRIMEIRO PASSO','Um guia para começar.','Conheça o modo local, as contas privadas e os limites de cada recurso.')+`<section class="panel prose"><h2>O que você já pode fazer</h2><ol><li><strong>Crie um projeto.</strong> Dê um nome, registre a referência e as funcionalidades prioritárias.</li><li><strong>Abra o editor.</strong> Uma página original ajuda a experimentar HTML, CSS e JavaScript. Ela não é um clone da URL.</li><li><strong>Acompanhe a prévia.</strong> A página roda isolada. Imagens externas, requisições e envio de formulários ficam bloqueados.</li><li><strong>Salve versões.</strong> Use pontos de recuperação antes de alterações importantes.</li><li><strong>Exporte um backup.</strong> Guarde os dados no seu celular. O HTML exportado deve ser revisado antes de publicar ou abrir conteúdo desconhecido.</li></ol><h2>O que ainda não está disponível</h2><p>Clonagem completa de sistemas, seleção visual para edição, execução de projetos com dependências, análise desktop, REA e testes de paridade. A IA local gera rascunhos sem testar o comportamento do site original.</p><h2>Privacidade primeiro</h2><p>O Studio não usa analytics. O modelo de IA é baixado de Hugging Face e GitHub somente após autorização; inferência local não envia o projeto a um provedor de IA. A captura de URL envia o endereço ao servidor da aplicação, que visita o site público. ${accounts.account.enabled?'Seus projetos são sincronizados com sua conta no Supabase.':'No modo local, seus projetos ficam neste navegador.'} Capturas importadas são exibidas como texto, não executadas.</p><h2>Sobre a skill</h2><p>A integração pessoal com <a href="https://github.com/darksemfiltro/clonar-programa" target="_blank" rel="noopener noreferrer">clonar-programa, do Dark Sem Filtro</a>, usa orientações internas para a geração no navegador. Seus scripts foram preservados no código-fonte, mas Node, REA e Playwright não são executados pelo navegador. A licença permite uso pessoal não comercial, com créditos e avisos preservados.</p><h2>No Android</h2><p>Use o painel no navegador. A experiência completa de extensões depende do navegador e não foi validada no aparelho. Faça backups: o endereço temporário de prévia pode mudar.</p></section>`;}
function aiPanel(p){return `<section class="ai-panel"><div class="section-title"><div><span class="kicker">DA REFERÊNCIA AO RASCUNHO</span><h2>O que você quer recriar?</h2></div><a href="#settings" class="text-link">Escolher IA / modo gratuito →</a></div><label class="sr-only" for="ai-request">Seu pedido</label><textarea id="ai-request" rows="2" maxlength="1200" placeholder="Ex.: recrie a estrutura da referência com cores verdes e bom uso no celular."></textarea><div class="stack-actions"><button class="button secondary" data-action="capture-url">1. Preparar referência</button><button class="button primary" data-action="ai-clone">2. Recriar referência</button><button class="button secondary" data-action="ai-design">Melhorar design</button><button class="button secondary" data-action="ai-review">Revisar qualidade</button><button class="button secondary" data-action="cancel-ai">Cancelar IA</button></div><div class="ai-status" role="status">${e(ai.runtime.message)}</div><progress class="ai-progress" max="1" value="${ai.runtime.progress}"></progress>${p.aiReport?`<details class="ai-report"><summary>Último resultado · rascunho não testado</summary><p>${e(p.aiReport.summary)}</p><ul>${p.aiReport.limitations.map(x=>`<li>${e(x)}</li>`).join('')}</ul></details>`:''}</section>`;}
async function captureReference(){
 if(!selected())return toast('Abra um projeto primeiro.');if(dirty&&!saveDraft())return;
 const p=selected(),captureOwner=accounts.account.owner;if(!p.target){editorTab='brief';render();toast('Preencha a URL da referência na entrevista.');return;}
 if(p.evidence.length>=10)return toast('Limite de 10 referências. Remova uma antes de capturar.');
 confirm('Capturar esta página pública?',`O servidor visitará ${p.target}. Use apenas páginas próprias ou autorizadas. Não informe links privados, tokens ou dados de clientes. A captura simples não executa JavaScript.`,async()=>{
  toast('Capturando a referência pública…');try{const res=await fetch('/api/capture',{method:'POST',headers:{'Content-Type':'application/json',...await accounts.authHeaders()},body:JSON.stringify({url:p.target,authorized:true}),signal:AbortSignal.timeout(25000)});const data=await res.json();if(!res.ok)throw Error(data.error||'Falha na captura.');const evidence=importEvidence(data);if(captureOwner!==accounts.account.owner)return;const latest=state.projects.find(x=>x.id===p.id);if(!latest)return;if(persist({...state,projects:state.projects.map(x=>x.id===p.id?{...latest,evidence:[...latest.evidence,evidence].slice(-10),updatedAt:new Date().toISOString()}:x)})){render();toast('Referência capturada. Revise em Referências antes de gerar.');}}catch(err){toast(err.message+' Você também pode importar uma captura da extensão.');}
 });
}
function offerGeneration(p,result){if(p.__owner!==accounts.account.owner)return toast('A conta mudou; este resultado não será aplicado.');
  const current=state.projects.find(x=>x.id===p.id);if(!current)return;
  if(JSON.stringify(current.files)!==JSON.stringify(p.files))return toast('Seu código mudou durante a geração. Não substituímos suas alterações; tente novamente com o código salvo.');
  confirm('Aplicar o rascunho gerado?',result.summary+' Limites: '+result.limitations.join(' ')+' O resultado não foi testado. Seu código atual será salvo como versão.',()=>{
   const latest=state.projects.find(x=>x.id===p.id);if(!latest)return;
   if(dirty&&currentId===p.id||JSON.stringify(latest.files)!==JSON.stringify(p.files))return toast('Seu código mudou após a geração. Resultado não aplicado para proteger suas alterações.');
   const updated={...latest,files:result.files,versions:[...latest.versions,{at:new Date().toISOString(),files:{...latest.files}}].slice(-10),updatedAt:new Date().toISOString(),aiReport:{summary:result.summary,limitations:result.limitations,at:new Date().toISOString()}};
   if(persist({...state,projects:state.projects.map(x=>x.id===p.id?updated:x)})){if(currentId===p.id){draft={...updated.files};dirty=false;}render();toast('Rascunho aplicado. Revise a prévia e teste as funcionalidades.');}
  });

}
async function runGeneration(task){
 if(!selected())return;if(dirty&&!saveDraft())return;
 const p=structuredClone(selected());p.__owner=accounts.account.owner;if(task==='clone'&&!p.evidence.length)return toast('Prepare ou importe uma referência antes de recriar.');
 const request=$('#ai-request')?.value||'';
 if(task==='clone'&&!p.brief.trim())return toast('Descreva as funcionalidades prioritárias na aba Entrevista.');
 try{
  if(ai.getProfile().provider==='manual')return manualGeneration(task,p,request);
  if(ai.getProfile().provider==='local'&&ai.runtime.state!=='ready')return toast('Ative a IA local em Administração ou escolha a validação sem API.');
  const result=await ai.generateWithProvider(task,p,request);
  offerGeneration(p,result);
 }catch(err){toast(err.message);}
}
async function manualGeneration(task,p,request){
 try{
  const messages=await ai.messagesFor(task,p,request);const prompt=messages.map(m=>m.role.toUpperCase()+':\n'+m.content).join('\n\n');
  let dialog=$('#manual-ai-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='manual-ai-dialog';dialog.className='manual-ai-dialog';dialog.innerHTML=`<h2>Validar sem API</h2><p>1. Copie o pedido e cole em uma IA que você já usa gratuitamente. Revise e retire dados privados antes de enviar.</p><textarea id="manual-prompt" rows="7" readonly aria-label="Pedido para IA"></textarea><div class="stack-actions"><button class="button primary" id="manual-copy">Copiar pedido</button><button class="button secondary" id="manual-download">Baixar pedido</button></div><p>2. Cole abaixo a resposta completa em JSON ou selecione o arquivo de resposta. O Studio vai validar antes de oferecer a aplicação.</p><textarea id="manual-response" rows="7" maxlength="200000" aria-label="Resposta da IA" placeholder="Cole a resposta aqui. Não cole chaves de API."></textarea><input type="file" id="manual-file" accept=".json,.txt,application/json,text/plain" aria-label="Arquivo de resposta da IA"><p id="manual-error" role="alert"></p><p class="muted">Processo manual, não um agente automático. A IA externa pode ter limites e política de dados próprios. O Studio não executou testes nem visitou o alvo por meio dessa IA.</p><div class="stack-actions"><button class="button secondary" id="manual-close">Fechar</button><button class="button primary" id="manual-apply">Conferir resposta</button></div>`;document.body.append(dialog);}
  $('#manual-prompt').value=prompt;$('#manual-response').value='';$('#manual-file').value='';$('#manual-error').textContent='';
  $('#manual-copy').onclick=async()=>{try{await navigator.clipboard.writeText(prompt);toast('Pedido copiado. Cole na IA que você já utiliza.');}catch{$('#manual-prompt').select();toast('O navegador bloqueou a cópia. Selecione e copie o texto ou baixe o pedido.');}};
  $('#manual-download').onclick=()=>download('baixatudo-pedido.txt',prompt,'text/plain');
  $('#manual-file').onchange=async event=>{const file=event.target.files[0];if(!file)return;if(file.size>200000){$('#manual-error').textContent='Resposta muito grande (máximo 200 KB).';return;}$('#manual-response').value=await file.text();};
  $('#manual-close').onclick=()=>dialog.close();
  $('#manual-apply').onclick=()=>{try{const result=parseGeneration($('#manual-response').value);dialog.close();offerGeneration(p,result);}catch(err){$('#manual-error').textContent=err.message;}};
  dialog.showModal();
 }catch(err){toast(err.message);}
}
window.addEventListener('studio-ai',()=>{if(ai.getProfile().provider==='local')document.querySelectorAll('.local-ai-status').forEach(el=>el.textContent=ai.runtime.message);document.querySelectorAll('.ai-status').forEach(el=>el.textContent=ai.runtime.message);document.querySelectorAll('.ai-progress').forEach(el=>el.value=ai.runtime.progress);});
function render(){
 if(accounts.account.status!=='local'&&accounts.account.status!=='ready'){$('#main').innerHTML=accountPage();$('#crumb').textContent='Minha conta';bindAccount();return;}
 clearTimeout(timer);if(dirty&&state.settings.autosave&&!saveDraft())return;
 const route=location.hash.slice(1)||'projects';const [page,id]=route.split('/');
 if(currentId!==id){if(dirty&&!saveDraft()){location.hash='project/'+currentId;return;}currentId=id||null;draft=id?{...state.projects.find(p=>p.id===id)?.files}:null;dirty=false;}
 const p=selected();
 $('#crumb').textContent=page==='project'?(p?.name||'Projeto não encontrado'):(names[page]||names.projects);
 document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===(page==='project'?'projects':page)));
 const body=page==='project'?(p?editorPage(p):heading('NÃO ENCONTRADO','Esse projeto não está aqui.','Ele pode ter sido removido ou pertencer a outro navegador.','<a class="button primary" href="#projects">Voltar aos projetos</a>')):({projects:projectsPage,activity:activityPage,skills:skillsPage,extension:extensionPage,settings:settingsPage,guide:guidePage,account:accountPage,admin:admin.page,import:importLanding}[page]||projectsPage)();
 $('#main').innerHTML=accountBanner()+(loadError?`<div class="notice error">${e(loadError)}</div>`:'')+body;
 updateShell();bindPage();bindAccount();if(page==='admin')admin.bind();updatePreview();$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');
}
function updatePreview(){const f=$('#preview');if(f&&draft){pickSelection=null;pickToken=crypto.randomUUID();const doc=buildDocument(draft,{preview:true});f.srcdoc=picking?inspectorDocument(doc,pickToken):doc;$('#visual-form fieldset')?.setAttribute('disabled','');if($('#visual-status'))$('#visual-status').textContent=picking?'Toque em um elemento estático na prévia.':'Seleção desativada. A prévia está interativa.';}}
window.addEventListener('message',event=>{const frame=$('#preview'),data=event.data;if(!picking||!frame||event.source!==frame.contentWindow||data?.kind!=='baixatudo-pick'||data.token!==pickToken)return;if(!Array.isArray(data.path)||typeof data.text!=='string'||data.text.length>2000)return;pickSelection={path:data.path,tag:data.tag,text:data.text};const form=$('#visual-form');if(!form)return;form.querySelector('fieldset').disabled=false;form.elements.text.value=data.text;form.elements.text.disabled=!data.leaf;$('#visual-status').textContent='Selecionado: '+String(data.tag).slice(0,20)+(data.leaf?'':' · contém filhos: somente estilo e ordem.');});
function bindPage(){
 $('#pick-toggle')?.addEventListener('click',()=>{picking=!picking;render();});
 function applyVisual(action='style'){if(!pickSelection||!draft)return;try{const form=$('#visual-form'),fields=new FormData(form),before={...draft};const updated=patchElement(draft.html,pickSelection,{action,text:fields.has('text')?String(fields.get('text')):undefined,color:String(fields.get('color')||''),background:String(fields.get('background')||''),fontSize:fields.get('fontSize')});const p=selected();if(!p)return;const next={...p,files:{...draft,html:updated},versions:[...p.versions,{at:new Date().toISOString(),files:before}].slice(-10),updatedAt:new Date().toISOString()};if(persist({...state,projects:state.projects.map(x=>x.id===p.id?next:x)})){draft={...next.files};dirty=false;render();toast('Edição visual salva; versão anterior preservada.');}}catch(error){toast(error.message);}}
 $('#visual-form')?.addEventListener('submit',event=>{event.preventDefault();applyVisual();});
 document.querySelectorAll('[data-visual]').forEach(button=>button.onclick=()=>applyVisual(button.dataset.visual));
 $('#quick-form')?.addEventListener('submit',ev=>{ev.preventDefault();const data=new FormData(ev.target);const title=data.get('title').trim();if(title){if(!/<h1\b[^>]*>[\s\S]*?<\/h1>/i.test(draft.html))return toast('A página não tem um título H1 para alterar.');draft.html=draft.html.replace(/(<h1\b[^>]*>)[\s\S]*?(<\/h1>)/i,(_,a,b)=>a+e(title)+b);}
 const bg=data.get('background'),fg=data.get('foreground');if(!/^#[a-f0-9]{6}$/i.test(bg)||!/^#[a-f0-9]{6}$/i.test(fg))return;
 draft.css=draft.css.replace(/\/\* Studio:cores \*\/[\s\S]*?\/\* Studio:fim \*\//g,'')+`\n/* Studio:cores */\nbody { background: ${bg}; color: ${fg}; }\n/* Studio:fim */`;
 dirty=true;if(saveDraft()){render();toast('Título e cores atualizados.');}});
 $('#search')?.addEventListener('input',ev=>{query=ev.target.value;const pos=ev.target.selectionStart;render();$('#search').focus();try{$('#search').setSelectionRange(pos,pos);}catch{}});
 $('#code')?.addEventListener('input',ev=>{draft[fileMode]=ev.target.value;dirty=true;$('#save-status').textContent='Alterações não salvas';clearTimeout(timer);timer=setTimeout(()=>{updatePreview();if(state.settings.autosave)saveDraft();},650);});
 $('#code')?.addEventListener('keydown',ev=>{if(ev.key==='Tab'){ev.preventDefault();const t=ev.target;const s=t.selectionStart;const end=t.selectionEnd;t.setRangeText('  ',s,end,'end');t.dispatchEvent(new Event('input'));}});
 $('#brief-form')?.addEventListener('submit',ev=>{ev.preventDefault();try{const d=Object.fromEntries(new FormData(ev.target));if(!d.name.trim())return;d.target=validateUrl(d.target);const p=selected();if(persist({...state,projects:state.projects.map(x=>x.id===p.id?{...p,...d,name:d.name.trim(),updatedAt:new Date().toISOString()}:x)})){toast('Entrevista salva.');render();}}catch(err){toast(err.message);}});
 $('#settings-form')?.addEventListener('submit',ev=>{ev.preventDefault();const d=new FormData(ev.target);if(persist({...state,settings:{name:d.get('name').trim()||'Meu espaço',autosave:d.has('autosave')}}))toast('Configurações salvas.');});
}
function selectFile(mode){if(dirty&&!saveDraft())return;importMode=mode;importProjectId=selected()?.id||null;importOwner=accounts.account.owner;$('#file-input').accept=mode==='backup'?'.json,application/json':'.json,.html,.htm,.txt,.md,.js,.css';$('#file-input').value='';$('#file-input').click();}
$('#file-input').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;if(file.size>MAX_IMPORT)return toast('Arquivo muito grande. O limite é 10 MB.');try{const mode=importMode,projectId=importProjectId;const owner=importOwner;const content=await file.text();if(owner!==accounts.account.owner)throw Error('A conta mudou. Selecione o arquivo novamente.');let raw;if(mode==='backup'){raw=JSON.parse(content);}else{if(file.size>500000||! /\.(json|html?|txt|md|js|css)$/i.test(file.name))throw Error('Use um arquivo textual de até 500 KB. ZIP, EXE e APK ainda não são suportados.');if(/\.json$/i.test(file.name)){try{raw=JSON.parse(content);}catch{}}if(raw?.kind!=='baixatudo-evidence')raw={kind:'baixatudo-evidence',version:1,page:{title:'Arquivo: '+file.name,url:'',text:content.slice(0,100000),capturedAt:new Date().toISOString()}};}if(mode==='backup'){const next=normalizeBackup(raw);confirm('Restaurar este backup?',`Os ${next.projects.length} projetos do arquivo substituirão os dados locais. Exporte seu backup atual antes de continuar.`,()=>{if(persist(next,{recover:true})){dirty=false;currentId=null;draft=null;location.hash='projects';render();toast('Backup restaurado.');}});}else{const evidence=importEvidence(raw);let p=state.projects.find(x=>x.id===projectId);if(!p){const now=new Date().toISOString();p={id:crypto.randomUUID(),name:evidence.title||'Projeto da referência',target:evidence.url,createdAt:now,updatedAt:now,brief:'',relation:'Estudo de comportamento',excluded:'',files:starterFiles(evidence.title||'Meu projeto'),evidence:[],versions:[]};if(!persist({...state,projects:[p,...state.projects]}))return;query='';filter='all';location.hash='project/'+p.id;}if(p.evidence.length>=10)throw Error('Limite de 10 referências por projeto.');if(persist({...state,projects:state.projects.map(x=>x.id===p.id?{...p,evidence:[...p.evidence,evidence],updatedAt:new Date().toISOString()}:x)})){render();toast('Captura importada como referência.');}}}catch(err){toast('Não foi possível importar: '+err.message);}};
$('#main').onclick=ev=>{
 const b=ev.target.closest('button, [data-action]');if(!b)return;
 if(b.dataset.action==='new')return createProject();if(b.dataset.action==='import-start')return selectFile('evidence');if(b.dataset.action==='backup')return exportBackup();
 if(b.dataset.filter){filter=b.dataset.filter;render();return;}
 if(b.dataset.delete)return confirm('Excluir projeto?','O projeto e suas versões serão removidos deste navegador.',()=>{if(persist({...state,projects:state.projects.filter(x=>x.id!==b.dataset.delete)}))render();});
 if(b.dataset.file){fileMode=b.dataset.file;render();return;}
 if(b.dataset.editorTab){editorTab=b.dataset.editorTab;render();return;}
 if(b.dataset.viewport){viewport=b.dataset.viewport;render();return;}
 const p=selected();
 if(b.hasAttribute('data-remove-evidence')){if(persist({...state,projects:state.projects.map(x=>x.id===p.id?{...p,evidence:p.evidence.filter((_,i)=>i!==Number(b.dataset.removeEvidence))}:x)}))render();return;}
 if(b.hasAttribute('data-restore')){const v=p.versions[Number(b.dataset.restore)];return confirm('Restaurar esta versão?','O código atual será guardado em um novo ponto de recuperação.',()=>{clearTimeout(timer);const updated={...p,files:{...v.files},versions:[...p.versions,{at:new Date().toISOString(),files:{...draft}}].slice(-10),updatedAt:new Date().toISOString()};if(persist({...state,projects:state.projects.map(x=>x.id===p.id?updated:x)})){draft={...v.files};dirty=false;render();toast('Versão restaurada.');}});}
 if(b.dataset.action==='forget-key'){ai.forgetKey();render();toast('Chave removida da memória desta aba.');return;}
 if(b.dataset.action==='capture-url')return captureReference();
 if(b.dataset.action==='ai-clone')return runGeneration('clone');
 if(b.dataset.action==='ai-design')return runGeneration('design');
 if(b.dataset.action==='ai-review')return runGeneration('review');
 if(b.dataset.action==='check-ai'){ai.support().then(result=>{const status=$('.local-ai-status');if(status)status.textContent=result.message+' Você pode continuar no modo manual ou usar uma API sem GPU local.';const activate=document.querySelector('[data-action="activate-ai"]');if(activate){activate.disabled=!result.ok;activate.title=result.ok?'':'GPU compatível não disponível neste navegador';}toast(result.message);});return;}
 if(b.dataset.action==='cancel-ai'){ai.cancel();toast('IA desativada. Projeto preservado.');return;}
 if(b.dataset.action==='activate-ai'){const id=$('#ai-model')?.value||MODELS[0].id;confirm('Baixar e ativar IA neste aparelho?','O modelo pode ocupar mais de 1 GB e consumir memória, bateria e internet. Use Wi-Fi. Não há API paga nem cadastro. A compatibilidade do aparelho será verificada.',()=>ai.activate(id).then(()=>toast('IA carregada. Abra seu projeto para gerar.')).catch(err=>toast(err.message)));return;}
 switch(b.dataset.action){case 'save':if(saveDraft())toast('Código salvo.');break;case 'refresh':updatePreview();break;case 'export-html':if(dirty&&!saveDraft())break;download('projeto.html',buildDocument(draft),'text/html');toast('HTML exportado. Revise antes de compartilhar.');break;case 'snapshot':if(!saveDraft())break;{const latest=selected();if(persist({...state,projects:state.projects.map(x=>x.id===p.id?{...latest,versions:[...latest.versions,{at:new Date().toISOString(),files:{...draft}}].slice(-10)}:x)})){render();toast('Ponto de recuperação salvo.');}}break;case 'import-backup':selectFile('backup');break;case 'import-evidence':selectFile('evidence');break;case 'clear':confirm('Apagar todo o espaço?','Esta ação remove todos os projetos e versões do espaço atual (conta, quando conectada, ou navegador local). Não pode ser desfeita sem backup.',()=>{if(persist({version:1,projects:[],settings:{name:'Meu espaço',autosave:true}},{recover:true})){dirty=false;draft=null;currentId=null;render();toast('Espaço atual apagado.');}});break;}
};
$('#menu-button').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-button').setAttribute('aria-expanded',String(open));};
$('#help-button').onclick=()=>location.hash='guide';
window.addEventListener('hashchange',render);
window.addEventListener('beforeunload',ev=>{if(dirty){if(state.settings.autosave&&saveDraft())return;ev.preventDefault();ev.returnValue='';}});
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key==='s'){ev.preventDefault();if(dirty)saveDraft();}if(ev.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');}if(ev.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&$('#search')){ev.preventDefault();$('#search').focus();}});
render();

document.addEventListener('submit',event=>{if(event.target.id!=='provider-form')return;event.preventDefault();const form=event.target,data=new FormData(form);try{ai.configure({provider:data.get('provider'),model:String(data.get('model')||'').trim()||(data.get('provider')==='openrouter'?'openrouter/free':''),freeOnly:data.has('freeOnly'),allowMetered:data.has('allowMetered')},String(data.get('apiKey')||''));form.elements.apiKey.value='';toast('Seleção salva. Nenhum pedido foi enviado ao provedor.');render();}catch{form.elements.apiKey.value='';toast('Não foi possível salvar a seleção. Verifique o armazenamento do navegador.');}});
document.addEventListener('change',event=>{if(event.target.id!=='provider-choice')return;const form=event.target.form;form.elements.model.value=OPTIONS.find(x=>x.id===event.target.value)?.model||'';form.elements.apiKey.value='';form.elements.allowMetered.checked=false;form.elements.freeOnly.checked=true;});

accounts.initialize();
